using System.Security.Claims;using LocalPro.Web.Data;using LocalPro.Web.Domain;using LocalPro.Web.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace LocalPro.Web.Pages;
[Authorize]public class MessagesModel(Marketplace m,AppDbContext db):PageModel{
 [BindProperty(SupportsGet=true)]public int? Pro{get;set;}[BindProperty(SupportsGet=true)]public string? Customer{get;set;}[BindProperty]public string Text{get;set;}="";public string UserId=>User.FindFirstValue(ClaimTypes.NameIdentifier)!;
 public List<Message> Items{get;set;}=[];public List<(int Pro,string Customer,string Name)> Threads{get;set;}=[];public string Name{get;set;}="";public string? Error{get;set;}
 public async Task OnGetAsync(){var owned=await db.Professionals.Where(p=>p.UserId==UserId).Select(p=>p.Id).ToListAsync();var msgs=await db.Messages.AsNoTracking().Where(x=>(x.CustomerId==UserId||owned.Contains(x.ProfessionalId))&&db.ServiceRequests.Any(r=>r.CustomerId==x.CustomerId&&r.ProfessionalId==x.ProfessionalId&&r.Status!=ServiceRequestStatus.Received&&r.Status!=ServiceRequestStatus.Cancelled)).OrderByDescending(x=>x.CreatedUtc).ToListAsync();foreach(var g in msgs.GroupBy(x=>new{x.ProfessionalId,x.CustomerId})){var p=await db.Professionals.FindAsync(g.Key.ProfessionalId);var name=owned.Contains(g.Key.ProfessionalId)?(await db.Users.FindAsync(g.Key.CustomerId))?.DisplayName:p?.Name;Threads.Add((g.Key.ProfessionalId,g.Key.CustomerId,name??"Customer"));}if(Pro.HasValue)try{Items=await m.Conversation(UserId,Pro.Value,Customer);Name=(await db.Professionals.FindAsync(Pro.Value))?.Name??"Conversation";}catch(RuleException ex){Error=ex.Message;Pro=null;}}
 public async Task<IActionResult> OnGetFeedAsync(){try{if(!Pro.HasValue)return BadRequest();return new JsonResult(await m.Conversation(UserId,Pro.Value,Customer));}catch(RuleException){return Forbid();}}
 public async Task<IActionResult> OnPostAsync(){try{if(!Pro.HasValue)throw new RuleException("Choose a conversation.");await m.Send(UserId,Pro.Value,Customer,Text);}catch(RuleException ex){TempData["Error"]=ex.Message;}return RedirectToPage(new{pro=Pro,customer=Customer});}}
